def smallest_divisor_ge_two_abs(x: int) -> int:
    n = abs(x)
    if n < 2:
        return 0
    for i in range(2, n + 1):
        if n % i == 0:
            return i
    return 0

def f(x):
    """Returns the number of decimal digits in abs(x) minus one."""
    return len(str(abs(x))) - 1
